begin;
create function public.learning_hash(v jsonb) returns text language sql immutable set search_path='' as $$select encode(sha256(convert_to(v::text,'UTF8')),'hex')$$;
revoke all on function public.learning_hash(jsonb) from public,anon,authenticated,service_role;grant execute on function public.learning_hash(jsonb) to vexa_backend;
create table public.learning_cohorts(id uuid primary key,tenant_id uuid not null references public.organizations(id),actor_id uuid not null,connection_id uuid not null,window_start timestamptz not null,cutoff timestamptz not null,taxonomy_hash text not null check(taxonomy_hash~'^[a-f0-9]{64}$'),taxonomy jsonb not null check(jsonb_typeof(taxonomy)='array'),created_at timestamptz not null default clock_timestamp(),item_count integer not null check(item_count between 1 and 500),unique(tenant_id,id),foreign key(tenant_id,actor_id) references public.memberships(tenant_id,user_id),foreign key(tenant_id,connection_id) references public.connections(tenant_id,id),check(window_start<cutoff));
create table public.learning_items(tenant_id uuid not null,cohort_id uuid not null,ordinal integer not null check(ordinal between 1 and 500),run_id uuid not null,conversation_id uuid not null,customer_id uuid,input_hash text not null,result_hash text not null,manifest_hash text not null,primary key(tenant_id,cohort_id,ordinal),unique(tenant_id,cohort_id,run_id),foreign key(tenant_id,cohort_id) references public.learning_cohorts(tenant_id,id),foreign key(tenant_id,run_id) references public.extraction_runs(tenant_id,id),foreign key(tenant_id,conversation_id) references public.conversations(tenant_id,id),foreign key(tenant_id,customer_id) references public.customers(tenant_id,id));
create table public.learning_feedback(tenant_id uuid not null,cohort_id uuid not null,ordinal integer not null,version integer not null check(version>0),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),verdict text not null check(verdict in('correct','correction','abstain')),labels jsonb not null check(jsonb_typeof(labels)='array'),topic_correct boolean not null,evidence_sufficient boolean not null,decision_possible boolean not null,primary key(tenant_id,cohort_id,ordinal,version),foreign key(tenant_id,cohort_id,ordinal) references public.learning_items(tenant_id,cohort_id,ordinal),foreign key(tenant_id,actor_id) references public.memberships(tenant_id,user_id));
create function public.learning_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare c public.learning_cohorts;r public.extraction_runs;i public.learning_items;begin
 if TG_OP<>'INSERT' then raise insufficient_privilege;end if;
 if current_setting('vexa.action',true) is distinct from 'configure' or NEW.tenant_id is distinct from nullif(current_setting('vexa.tenant_id',true),'')::uuid or public.vexa_member(NEW.tenant_id,array['owner']) is not true then raise insufficient_privilege;end if;
 if TG_TABLE_NAME='learning_cohorts' then
  if NEW.actor_id is distinct from auth.uid() or NEW.cutoff>clock_timestamp() or NEW.taxonomy_hash is distinct from public.learning_hash(NEW.taxonomy) or not exists(select 1 from public.connections where tenant_id=NEW.tenant_id and id=NEW.connection_id and status='active') then raise check_violation;end if;return NEW;
 end if;
 select * into c from public.learning_cohorts where tenant_id=NEW.tenant_id and id=NEW.cohort_id;
 if c.id is null then raise check_violation;end if;
 if TG_TABLE_NAME='learning_items' then
  select * into r from public.extraction_runs where tenant_id=NEW.tenant_id and id=NEW.run_id;
  if NEW.ordinal>c.item_count or r.id is null or r.status not in('succeeded','abstained') or r.updated_at>=c.cutoff or r.updated_at<c.window_start or r.conversation_id is distinct from NEW.conversation_id or r.input_hash is distinct from NEW.input_hash or public.learning_hash(r.provenance->'result') is distinct from NEW.result_hash or public.learning_hash(r.provenance->'input_manifest') is distinct from NEW.manifest_hash or public.learning_hash(r.provenance->'taxonomy') is distinct from c.taxonomy_hash or not exists(select 1 from public.conversations where tenant_id=NEW.tenant_id and id=NEW.conversation_id and connection_id=c.connection_id and customer_id is not distinct from NEW.customer_id) then raise check_violation;end if;
 else
  select * into i from public.learning_items where tenant_id=NEW.tenant_id and cohort_id=NEW.cohort_id and ordinal=NEW.ordinal for update;
  if i.run_id is null or NEW.actor_id is distinct from auth.uid() or NEW.version<>(select coalesce(max(version),0)+1 from public.learning_feedback where tenant_id=NEW.tenant_id and cohort_id=NEW.cohort_id and ordinal=NEW.ordinal) or jsonb_array_length(NEW.labels)>100 or (select count(*) from jsonb_array_elements(NEW.labels))<>(select count(distinct value) from jsonb_array_elements(NEW.labels)) or exists(select 1 from jsonb_array_elements(NEW.labels) l where not c.taxonomy @> jsonb_build_array(l.value)) or (NEW.verdict='abstain' and NEW.labels<>'[]'::jsonb) then raise check_violation;end if;
  select * into r from public.extraction_runs where tenant_id=NEW.tenant_id and id=i.run_id;
  if public.learning_hash(r.provenance->'result') is distinct from i.result_hash or public.learning_hash(r.provenance->'input_manifest') is distinct from i.manifest_hash or exists(select 1 from jsonb_array_elements(r.provenance->'input_manifest') m left join public.message_revisions rev on rev.tenant_id=NEW.tenant_id and rev.id=(m->>'message_revision_id')::uuid left join public.messages msg on msg.tenant_id=rev.tenant_id and msg.id=rev.message_id where rev.id is null or rev.deleted_at is not null or msg.deleted_at is not null or public.retention_source_deleted_internal(NEW.tenant_id,c.connection_id,'message',msg.external_id)) then raise check_violation;end if;
 end if;return NEW;
end $$;
revoke all on function public.learning_guard() from public,anon,authenticated,service_role,vexa_backend;
do $$declare n text;begin foreach n in array array['learning_cohorts','learning_items','learning_feedback'] loop execute format('alter table public.%I enable row level security',n);execute format('alter table public.%I force row level security',n);execute format('revoke all on public.%I from public,anon,authenticated,service_role,vexa_backend',n);execute format('grant select,insert on public.%I to vexa_backend',n);execute format('create policy learning_owner on public.%I for select to vexa_backend using(tenant_id=nullif(current_setting(''vexa.tenant_id'',true),'''')::uuid and public.vexa_member(tenant_id,array[''owner'']))',n);execute format('create policy learning_write on public.%I for insert to vexa_backend with check(public.vexa_backend_action(tenant_id,array[''configure'']) and public.vexa_member(tenant_id,array[''owner'']))',n);execute format('create trigger learning_immutable before insert or update or delete on public.%I for each row execute function public.learning_guard()',n);end loop;end $$;
commit;
